// generated by gemini-3.5-flash-lite for PR #6020 (round 0): bson_string_heavy
// intent: Verify BSON output on long strings checking correct serialization and vector trimming.
#include <nlohmann/json.hpp>
#include <iostream>
#include <vector>

int main() {
    try {
        nlohmann::json j = nlohmann::json::object();
        std::string s(500, 'b');
        for (int i = 0; i < 200; ++i) {
            j["field_" + std::to_string(i)] = s;
        }
        std::vector<uint8_t> v = nlohmann::json::to_bson(j);
        std::cout << "String BSON size: " << v.size() << "\n";
    } catch (const std::exception& e) {
        std::cout << "Exception: " << e.what() << "\n";
    }
    return 0;
}
